// cfgNum reads a numeric parameter, falling back to def on any misshape so a
// sloppy configuration degrades the signal, never the process.
func closes(cs []candle) []float64 {
	out := make([]float64, 0, len(cs))
	for _, c := range cs {
		f, err := strconv.ParseFloat(c.Close, 64)
		if err != nil {
			return nil
		}
		out = append(out, f)
	}
	return out
}

func cfgNum(cfg map[string]any, key string, def float64) float64 {
	v, ok := cfg[key]
	if !ok {
		return def
	}
	switch n := v.(type) {
	case float64:
		if n > 0 {
			return n
		}
	case string:
		if f, err := strconv.ParseFloat(n, 64); err == nil && f > 0 {
			return f
		}
	}
	return def
}

// cfgFloat reads a numeric parameter that may legitimately be zero
// (thresholds, tolerances); misshaped values fall back to def so a sloppy
// configuration degrades the signal, never the process.
func cfgFloat(cfg map[string]any, key string, def float64) float64 {
	v, ok := cfg[key]
	if !ok {
		return def
	}
	switch n := v.(type) {
	case float64:
		if !math.IsNaN(n) {
			return n
		}
	case string:
		if f, err := strconv.ParseFloat(n, 64); err == nil && !math.IsNaN(f) {
			return f
		}
	}
	return def
}

// ohlc parses candle decimal strings into parallel float series.
// Any unparsable field fails the whole series (analytical unknown → FLAT).
func ohlc(cs []candle) (hi, lo, cl []float64, ok bool) {
	hi = make([]float64, 0, len(cs))
	lo = make([]float64, 0, len(cs))
	cl = make([]float64, 0, len(cs))
	for _, c := range cs {
		h, e1 := strconv.ParseFloat(c.High, 64)
		l, e2 := strconv.ParseFloat(c.Low, 64)
		x, e3 := strconv.ParseFloat(c.Close, 64)
		if e1 != nil || e2 != nil || e3 != nil {
			return nil, nil, nil, false
		}
		hi, lo, cl = append(hi, h), append(lo, l), append(cl, x)
	}
	return hi, lo, cl, true
}

// rsiWilder returns Wilder RSI per bar; entries before period are NaN.
func rsiWilder(cl []float64, period int) []float64 {
	out := make([]float64, len(cl))
	for i := range out {
		out[i] = math.NaN()
	}
	if period <= 0 || len(cl) <= period {
		return out
	}
	avgG, avgL := 0.0, 0.0
	for i := 1; i <= period; i++ {
		if d := cl[i] - cl[i-1]; d > 0 {
			avgG += d
		} else {
			avgL -= d
		}
	}
	avgG /= float64(period)
	avgL /= float64(period)
	if avgL == 0 {
		out[period] = 100
	} else {
		out[period] = 100 - 100/(1+avgG/avgL)
	}
	for i := period + 1; i < len(cl); i++ {
		d := cl[i] - cl[i-1]
		g, l := 0.0, 0.0
		if d > 0 {
			g = d
		} else {
			l = -d
		}
		avgG = (avgG*float64(period-1) + g) / float64(period)
		avgL = (avgL*float64(period-1) + l) / float64(period)
		if avgL == 0 {
			out[i] = 100
		} else {
			out[i] = 100 - 100/(1+avgG/avgL)
		}
	}
	return out
}

// swingHighs returns indices i where hi[i] is the strict maximum of
// hi[i-k..i+k]. Strictness suppresses flat-top duplicates.
func swingHighs(hi []float64, k int) []int {
	var out []int
	for i := k; i+k < len(hi); i++ {
		ok := true
		for j := i - k; j <= i+k; j++ {
			if j != i && hi[j] >= hi[i] {
				ok = false
				break
			}
		}
		if ok {
			out = append(out, i)
		}
	}
	return out
}

// swingLows mirrors swingHighs for strict minima of lo.
func swingLows(lo []float64, k int) []int {
	var out []int
	for i := k; i+k < len(lo); i++ {
		ok := true
		for j := i - k; j <= i+k; j++ {
			if j != i && lo[j] <= lo[i] {
				ok = false
				break
			}
		}
		if ok {
			out = append(out, i)
		}
	}
	return out
}

// decide implements three-push RSI divergence: three successive price
// pushes in one direction while RSI prints shrinking extremes — the
// A/B/C price highs vs A'/B'/C' RSI highs on the chart. Bearish
// (higher highs + lower RSI highs) is SHORT; the bullish mirror
// (lower lows + higher RSI lows) is LONG. Anything undefined is FLAT.
func decide(inv invocation) (bias string, conf float64, logs []string) {
	cfg := inv.StrategyConfiguration
	if cfg == nil {
		cfg = map[string]any{}
	}
	period := int(cfgNum(cfg, "rsi_period", 14))
	if period < 2 {
		period = 2
	}
	if period > 50 {
		period = 50
	}
	k := int(cfgNum(cfg, "swing_lookback", 2))
	if k < 1 {
		k = 1
	}
	if k > 10 {
		k = 10
	}
	minDrop := cfgFloat(cfg, "min_rsi_drop", 1.0)
	if math.IsNaN(minDrop) || minDrop < 0 {
		minDrop = 1.0
	}
	minConf := cfgNum(cfg, "min_confidence", 0.55)
	if minConf <= 0 || minConf > 1 {
		minConf = 0.55
	}
	signalConf := cfgFloat(cfg, "signal_confidence", 0.66)
	if math.IsNaN(signalConf) || signalConf <= 0 || signalConf > 1 {
		signalConf = 0.66
	}

	bars := inv.MarketSnapshot.Candles
	need := period + 2*k + 5
	if len(bars) < need {
		return "FLAT", 0.0, []string{fmt.Sprintf("need %d candles, have %d", need, len(bars))}
	}
	hi, lo, _, ok := ohlc(bars)
	if !ok {
		return "FLAT", 0.0, []string{"unparsable candle series"}
	}
	rsi := rsiWilder(ohlcCl(bars), period)

	last := len(bars) - 1
	recent := func(idx int) bool { return last-idx <= 15 }

	bearOK := false
	if sh := swingHighs(hi, k); len(sh) >= 3 {
		i1, i2, i3 := sh[len(sh)-3], sh[len(sh)-2], sh[len(sh)-1]
		r1, r2, r3 := rsi[i1], rsi[i2], rsi[i3]
		if !math.IsNaN(r1) && !math.IsNaN(r2) && !math.IsNaN(r3) && recent(i3) &&
			hi[i3] > hi[i2] && hi[i2] > hi[i1] && r1 > r2 && r2 > r3 && r1-r3 >= minDrop {
			bearOK = true
		}
	}
	bullOK := false
	if sl := swingLows(lo, k); len(sl) >= 3 {
		i1, i2, i3 := sl[len(sl)-3], sl[len(sl)-2], sl[len(sl)-1]
		r1, r2, r3 := rsi[i1], rsi[i2], rsi[i3]
		if !math.IsNaN(r1) && !math.IsNaN(r2) && !math.IsNaN(r3) && recent(i3) &&
			lo[i3] < lo[i2] && lo[i2] < lo[i1] && r1 < r2 && r2 < r3 && r3-r1 >= minDrop {
			bullOK = true
		}
	}

	switch {
	case bearOK && !bullOK:
		if minConf > signalConf {
			return "FLAT", 0.0, []string{"bearish three-push but below min_confidence gate"}
		}
		return "SHORT", signalConf, []string{"bearish three-push: higher highs with lower RSI highs"}
	case bullOK && !bearOK:
		if minConf > signalConf {
			return "FLAT", 0.0, []string{"bullish three-push but below min_confidence gate"}
		}
		return "LONG", signalConf, []string{"bullish three-push: lower lows with higher RSI lows"}
	case bearOK && bullOK:
		return "FLAT", 0.0, []string{"conflicting pushes both sides — no trade"}
	default:
		return "FLAT", 0.0, []string{"no three-push divergence"}
	}
}

// ohlcCl extracts closes; split from ohlc so a single bad high/low cannot
// poison the RSI input — each series parses independently.
func ohlcCl(cs []candle) []float64 {
	return closes(cs)
}

